<script lang="ts">
  import UiIcon from './UiIcon.svelte';
  import PlayerAvatar from './PlayerAvatar.svelte';
  import VersionIcon from './VersionIcon.svelte';
  import LoaderLogo from './LoaderLogo.svelte';
  import { t } from './i18n';

  type Category='installed'|'release'|'forge'|'fabric'|'neoforge'|'quilt'|'optifine'|'snapshot'|'old';
  let {
    username=$bindable('Steve'), selectedVersion=$bindable(''), ramGb=$bindable(4),
    category, options, collapsed=false, premium=false, skinUrl='', maxMemory=16,
    recommendedJava=null, javaStatus='', busy=false, preparing=false, packName='',
    message='', catalogError='', ontoggle, oncategory, onversionchange, onconfig,
    onmemorycommit, onlaunch, onclearpack, onoptifinedownload,
  }: {
    username:string;selectedVersion:string;ramGb:number;category:Category;
    options:{id:string;label:string}[];collapsed?:boolean;premium?:boolean;skinUrl?:string;
    maxMemory?:number;recommendedJava?:number|null;javaStatus?:string;busy?:boolean;
    preparing?:boolean;packName?:string;message?:string;catalogError?:string;
    ontoggle:()=>void;oncategory:(category:Category)=>void;onversionchange:()=>void;
    onconfig:()=>void;onmemorycommit:()=>void;onlaunch:()=>void;onclearpack:()=>void;onoptifinedownload?:()=>void;
  }=$props();
  const categories:{id:Category;label:string}[]=[
    {id:'installed',label:'Instaladas'},{id:'release',label:'Releases'},
    {id:'forge',label:'Forge'},{id:'fabric',label:'Fabric'},{id:'neoforge',label:'NeoForge'},{id:'quilt',label:'Quilt'},{id:'optifine',label:'OptiFine'},
    {id:'snapshot',label:'Snapshots'},{id:'old',label:'Betas / Alphas'},
  ];
  let currentMissing=$derived(!!selectedVersion&&!options.some(option=>option.id===selectedVersion));
  let canLaunch=$derived(!busy&&!preparing&&!!selectedVersion.trim()&&(options.length>0||currentMissing));
  let javaLabel=$derived(recommendedJava===null?'Java: consultando…':`Java ${Math.max(8,recommendedJava)} · ${javaStatus}`);
  let feedback=$derived(catalogError||message);
  let feedbackError=$derived(!!catalogError||/^(error|no se pudo)/i.test(message));
</script>

<footer class="launch-dock" class:collapsed aria-label={$t('Barra de juego rápido')}>
  <div class="dock-rail"><span class="rail-line"></span><button class="dock-toggle" onclick={ontoggle} aria-expanded={!collapsed} aria-controls="quick-launch-controls" aria-label={$t(collapsed?'Mostrar barra de juego':'Ocultar barra de juego')} title={$t(collapsed?'Mostrar barra de juego':'Ocultar barra de juego')}><span class:points-up={collapsed}><UiIcon name="down" size={17}/></span></button><span class="rail-line"></span></div>
  <div class="dock-controls" id="quick-launch-controls" hidden={collapsed}>
      <div class="dock-player"><PlayerAvatar {skinUrl} name={username} size={31}/><div><label for="dock-player-name">{$t(premium?'Cuenta Microsoft':'Nick del jugador')}</label><input id="dock-player-name" value={username} disabled={premium||busy||preparing} oninput={event=>{username=event.currentTarget.value;onconfig();}} maxlength="16" spellcheck="false" autocomplete="off" placeholder="Steve" data-no-translate/></div></div>
      <div class="dock-version"><div class="version-caption">{#if category==='release'}<VersionIcon name="release"/>{:else if category==='snapshot'}<VersionIcon name="snapshot"/>{:else if category==='old'}<VersionIcon name="legacy"/>{:else if category==='installed'}<UiIcon name="grid" size={16}/>{:else}<LoaderLogo loader={category} size={16}/>{/if}<label for="dock-version">{$t(packName?'Modpack activo':'Versión de Minecraft')}</label>{#if packName}<button class="clear-pack" onclick={onclearpack} disabled={busy||preparing} aria-label={$t('Usar perfil normal')} title={$t('Usar perfil normal')}><UiIcon name="close" size={13}/></button>{/if}<small title={javaLabel} data-no-translate>{javaLabel}</small></div><div class="version-selectors"><select aria-label={$t('Filtrar versiones')} value={category} onchange={event=>oncategory(event.currentTarget.value as Category)} disabled={busy||preparing}>{#each categories as item}<option value={item.id}>{$t(item.label)}</option>{/each}</select><select id="dock-version" value={selectedVersion} onchange={event=>{selectedVersion=event.currentTarget.value;onversionchange();}} disabled={busy||preparing||!options.length} title={packName||options.find(option=>option.id===selectedVersion)?.label||selectedVersion} data-no-translate>{#if currentMissing}<option value={selectedVersion}>{selectedVersion} · {$t('Selección actual')}</option>{/if}{#if !options.length&&!currentMissing}<option value="">{$t('Sin versiones disponibles')}</option>{/if}{#each options as option}<option value={option.id}>{option.label}</option>{/each}</select></div></div>
      <div class="dock-memory"><label for="dock-memory"><UiIcon name="chip" size={12}/><span>RAM</span><strong>{ramGb} GB</strong></label><input id="dock-memory" type="range" min="2" max={Math.max(2,Math.min(128,Math.floor(maxMemory)))} step="1" value={ramGb} oninput={event=>{ramGb=Number(event.currentTarget.value);onconfig();}} onchange={onmemorycommit} disabled={busy||preparing}/></div>
      <button class="dock-play" onclick={()=>{if(category==='optifine'&&!options.length)onoptifinedownload?.();else onlaunch();}} disabled={!canLaunch&&!(category==='optifine'&&!options.length&&!busy&&!preparing)}><UiIcon name={busy||preparing?'refresh':'play'} size={19}/><span>{$t(preparing?'INSTALANDO…':busy?'PREPARANDO…':category==='optifine'&&!options.length?'DESCARGAR OPTIFINE':'JUGAR AHORA')}</span></button>
      {#if feedback}<p class="dock-feedback" class:error={feedbackError} role="status" title={feedback} data-diagnostic>{feedback}</p>{/if}
  </div>
</footer>

<style>
  .dock-controls[hidden]{display:none}
  .launch-dock{flex:0 0 auto;min-width:0;position:relative;z-index:8;background:rgba(var(--bg-base-rgb),.96);box-shadow:0 -8px 24px #0003,inset 0 1px #d5e6cb15;backdrop-filter:blur(var(--blur-px,12px))}.dock-rail{height:20px;display:flex;align-items:center;gap:0;padding:0 19px}.rail-line{flex:1;height:1px;background:linear-gradient(90deg,transparent,#a6b99c35)}.rail-line:last-child{transform:scaleX(-1)}button,input,select{font:inherit}button{cursor:pointer}.dock-toggle{display:grid;place-items:center;width:61px;height:22px;border:1px solid rgba(var(--primary-rgb),.35);border-top:0;border-radius:0 0 4px 4px;background:rgba(var(--primary-rgb),.12);color:var(--primary);flex-shrink:0;padding:0;align-self:flex-start}.dock-toggle>span{display:flex;transition:transform .18s}.dock-toggle .points-up{transform:rotate(180deg)}.dock-controls{display:grid;grid-template-columns:minmax(125px,.8fr) minmax(250px,2.4fr) minmax(95px,.65fr) minmax(140px,.85fr);gap:14px;align-items:center;padding:9px 24px 14px}.dock-player{display:flex;align-items:center;gap:9px;min-width:0}.dock-player>div{min-width:0;flex:1}.dock-controls label{display:flex;align-items:center;gap:6px;color:#98a9a0;font-size:.6rem;line-height:1.4;margin:0 0 7px}.dock-player input{width:100%;box-sizing:border-box;background:#0002;border:1px solid #ffffff16;border-radius:3px;padding:8px 9px;color:#e2e9de;font-size:.74rem;min-width:0}.dock-player input:disabled{opacity:.8;color:#c4d4c7}.dock-version{min-width:0}.version-caption{display:flex;align-items:center;gap:7px;min-width:0;margin-bottom:7px}.version-caption label{margin:0;white-space:nowrap}.version-caption small{margin-left:auto;font-size:.55rem;color:#7e9684;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;line-height:1.4}.clear-pack{width:18px;height:18px;display:grid;place-items:center;border:1px solid #ffffff18;background:#ffffff06;color:#a8b6a6;border-radius:2px;padding:0}.version-selectors{display:grid;grid-template-columns:108px minmax(0,1fr);gap:6px}.version-selectors select{box-sizing:border-box;width:100%;min-width:0;border:1px solid #b6c4b22a;border-radius:3px;padding:8px 24px 8px 9px;background:rgba(var(--bg-base-rgb),.95);color:#dbe5d6;line-height:1.35;font-size:.73rem;color-scheme:dark;white-space:nowrap;text-overflow:ellipsis;height:35px}.version-selectors select:first-child{font-size:.65rem;color:#aebda8}.dock-memory label{margin-bottom:11px}.dock-memory strong{margin-left:auto;color:var(--primary);font-size:.65rem;font-weight:600;white-space:nowrap}.dock-memory input{display:block;width:100%;height:5px;accent-color:var(--primary);margin:0;cursor:pointer}.dock-play{min-height:47px;display:flex;align-items:center;justify-content:center;gap:9px;padding:10px 12px;border:1px solid rgba(var(--primary-rgb),.65);border-bottom:3px solid color-mix(in srgb,var(--primary) 45%,#000);border-radius:3px;background:linear-gradient(180deg,color-mix(in srgb,var(--primary) 85%,#fff),var(--primary));color:#0b1210;font:400 .68rem/1.6 var(--font-display);box-shadow:inset 0 1px #ffffff40;white-space:nowrap}.dock-play:hover:not(:disabled){filter:brightness(1.1)}button:disabled,select:disabled,input:disabled{cursor:default}.dock-play:disabled{opacity:.55;filter:saturate(.5)}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--primary);outline-offset:3px}.dock-feedback{grid-column:1/-1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#91a88f;font-size:.64rem;line-height:1.5;margin:-3px 0 0}.dock-feedback.error{color:#e6a6ac}.collapsed{box-shadow:0 -1px #b1c5a52b}.collapsed .dock-rail{height:24px}.collapsed .dock-toggle{height:24px}.collapsed .rail-line{opacity:.7}
  @media(max-width:1280px){.dock-controls{grid-template-columns:minmax(105px,.8fr) minmax(220px,2.5fr) 90px 134px;gap:10px;padding-left:18px;padding-right:18px}.dock-player :global(canvas){display:none}.version-caption small{max-width:120px}.dock-play{font-size:.61rem}.version-selectors{grid-template-columns:95px minmax(0,1fr)}}
  @media(max-width:1050px){.dock-controls{grid-template-columns:128px minmax(200px,1fr) 140px;gap:10px 13px;padding:8px 16px 12px}.dock-memory{grid-column:1;grid-row:2;display:flex;align-items:center;gap:10px}.dock-memory label{margin:0;gap:5px}.dock-memory label :global(svg){display:none}.dock-memory strong{margin:0}.dock-memory input{flex:1;min-width:35px}.dock-version{grid-column:2;grid-row:1/3}.dock-play{grid-column:3;grid-row:1/3}.dock-player label{margin-bottom:5px}.dock-player input{padding:6px 8px}.version-caption small{display:none}.version-selectors{grid-template-columns:95px minmax(0,1fr)}.dock-feedback{grid-row:3}}
  @media(max-width:760px){.dock-controls{grid-template-columns:minmax(100px,.9fr) minmax(170px,1.6fr);gap:10px 12px}.dock-player{grid-column:1;grid-row:1}.dock-version{grid-column:2;grid-row:1}.dock-memory{grid-column:1;grid-row:2}.dock-play{grid-column:2;grid-row:2;min-height:35px;padding:6px 10px;font-size:.6rem}.version-selectors{grid-template-columns:82px minmax(0,1fr);gap:5px}.version-selectors select{font-size:.66rem;height:32px;padding-left:6px}.version-selectors select:first-child{font-size:.57rem}.version-caption label,.dock-player label{font-size:.55rem}.dock-player input{height:32px}.dock-feedback{font-size:.6rem}}
  @media(max-width:460px){.dock-controls{grid-template-columns:minmax(84px,.8fr) minmax(150px,1.5fr);padding:7px 9px 10px;gap:9px}.dock-rail{padding:0 9px}.version-selectors{grid-template-columns:minmax(0,1fr)}.version-selectors select:first-child{display:block}.dock-memory label>span{display:none}.dock-memory{gap:7px}.dock-feedback{max-height:2.8em;white-space:normal;display:-webkit-box;-webkit-line-clamp:2;line-clamp:2;-webkit-box-orient:vertical}}
  @media(prefers-reduced-motion:reduce){.dock-toggle>span{transition:none}}
</style>
